{
  "steps": [
    {
      "id": "s1",
      "agent_id": "researcher",
      "description": "Gather and summarize up-to-date, citable information on sodium‑ion and lithium‑ion home battery systems relevant to residential use. For each chemistry collect: typical energy density (Wh/kg or Wh/L), cost per kWh (manufacturing and installed/system), cycle life (cycles at recommended DOD), calendar life (years), round‑trip efficiency (%), typical usable depth of discharge, temperature operating range and thermal management needs, safety incidents/thermal runaway risk, material supply chain and scarcity (e.g., Li, Na, Co, Ni), recycling/end‑of‑life pathways, representative commercial products and their specs and prices, and notable field deployments. Produce a concise markdown summary with a short conclusions section and a bibliography of URLs for every fact or figure.",
      "dependencies": [],
      "produces": "raw_research.md",
      "consumes": [],
      "rationale": "web search and market discovery specialist needed to collect current specs, prices, and citations",
      "needs_tools": [
        "web_search"
      ]
    },
    {
      "id": "s2",
      "agent_id": "data_analyst",
      "description": "Extract quantitative data from raw_research.md and produce a cleaned numeric comparison table (CSV) with rows for metrics (energy_density_Wh_per_kg, cost_per_kWh_USD, cycle_life_cycles, calendar_life_years, round_trip_efficiency_pct, usable_DOD_pct, operating_temp_range_C, safety_score, recycling_score) and columns for sodium_ion and lithium_ion. Where ranges exist, record central estimate and uncertainty columns. Normalize the metrics to a 0–100 suitability score for residential home-battery use and compute a weighted overall suitability score using a defensible weighting (include the weighting rationale). Save the CSV and a short 1‑page analysis summary of key numeric differences.",
      "dependencies": [
        "s1"
      ],
      "produces": "quantitative_comparison.csv",
      "consumes": [
        "raw_research.md"
      ],
      "rationale": "to convert collected facts into objective numeric comparisons and an aggregate score",
      "needs_tools": [
        "read_file"
      ]
    },
    {
      "id": "s3",
      "agent_id": "creative",
      "description": "Produce a final recommendation report (markdown) for a homeowner choosing between sodium‑ion and lithium‑ion home batteries. Use raw_research.md and quantitative_comparison.csv. The report must include: a 3‑sentence executive summary with a single clear recommendation (pick one chemistry), a short justification grounded in the numeric analysis and practical considerations (cost, safety, lifecycle, availability), pros and cons for each chemistry, scenarios/household types where the non‑recommended option might be preferable, a short purchasing checklist (specs to ask vendors), and next steps (installation, warranties, recycling). Cite the key sources and show the overall suitability scores from the CSV.",
      "dependencies": [
        "s1",
        "s2"
      ],
      "produces": "final_recommendation_report.md",
      "consumes": [
        "raw_research.md",
        "quantitative_comparison.csv"
      ],
      "rationale": "to synthesize findings into a homeowner‑facing recommendation and action checklist",
      "needs_tools": [
        "read_file",
        "write_file"
      ]
    }
  ]
}
